#!/usr/bin/env python3
"""Generates spleen.h (the player's bitmap fonts) from the Spleen BDF files.

    python gen_font.py spleen-6x12.bdf spleen-12x24.bdf > spleen.h

Spleen: https://github.com/fcambus/spleen (BSD 2-clause, see LICENSE).
Only code points 32-255 (ASCII + Latin-1) are kept; each row is a uint16, left-aligned on bit 15.
"""
import sys


def read_bdf(path):
    glyphs, fw, fh, fx, fy = {}, 0, 0, 0, 0
    lines = iter(open(path, encoding='latin-1').read().splitlines())
    for line in lines:
        if line.startswith('FONTBOUNDINGBOX'):
            fw, fh, fx, fy = map(int, line.split()[1:5])
        elif line.startswith('ENCODING'):
            code = int(line.split()[1])
        elif line.startswith('BBX'):
            w, h, x, y = map(int, line.split()[1:5])
        elif line == 'BITMAP':
            rows = []
            for row in lines:
                if row == 'ENDCHAR':
                    break
                rows.append(int(row, 16) << (16 - 4 * len(row)))   # left-align on 16 bits
            cell = [0] * fh
            top = (fh + fy) - (h + y)                                 # glyph rows from the cell top
            for i, r in enumerate(rows):
                if 0 <= top + i < fh:
                    cell[top + i] = (r >> (x - fx)) & 0xFFFF
            if 32 <= code <= 255:
                glyphs[code] = cell
    return fw, fh, glyphs


def main():
    print('/* Generated by gen_font.py from the Spleen fonts (c) Frederic Cambus, BSD 2-clause (see LICENSE). */')
    print('/* Code points 32-255; one uint16 per row, left-aligned on bit 15. */')
    for path in sys.argv[1:]:
        w, h, g = read_bdf(path)
        print(f'#define SPLEEN_{w}X{h}_W {w}\n#define SPLEEN_{w}X{h}_H {h}')
        print(f'static const uint16_t SPLEEN_{w}X{h}[224][{h}] = {{')
        for c in range(32, 256):
            rows = g.get(c, g.get(ord('?')))
            print('    {' + ','.join(f'0x{r:04x}' for r in rows) + f'}},  /* {c} */')
        print('};')


main()
